(* [comment removed for export] *)
Lemma range_bv_eq8 : forall (e c : Z -> Z) lo hi,
  forallb_range (fun z => negb (z mod 8 =? 0) || Z.eqb (e z mod 2^64) (c z mod 2^64)) lo (Z.to_nat (hi - lo + 1)) = true ->
