Definition class_ok (s : Z) : bool :=
  let c := class_id s in let S := size_of_class c in
  (1 <=? c) && (c <=? 30) && (s <=? S) && (S <=? 65536) && (S mod 16 =? 0) && (16 <=? S)
  && (implb (s <=? 512) (c =? Z.shiftr (s + 31) 5)) && (implb (512 <? s) (17 <=? c)).

